<?php
require_once 'layout.php'; admin_require_login(); require_once '../includes/db_connect.php';
$appId = filter_input(INPUT_GET, 'id', FILTER_VALIDATE_INT); if (!$appId) { header('Location: view_applicants.php'); exit(); } $error = '';
$allowed = ['Applied', 'Pending', 'Shortlisted', 'Selected', 'Rejected'];
if ($_SERVER['REQUEST_METHOD'] === 'POST') { $status = $_POST['status'] ?? ''; if (!in_array($status, $allowed, true)) $error = 'Select a valid status.'; else { $stmt = $conn->prepare('UPDATE application SET status = ? WHERE application_id = ?'); $stmt->bind_param('si', $status, $appId); if ($stmt->execute()) { header('Location: view_applicants.php'); exit(); } $error = 'Could not update the application.'; } }
$stmt = $conn->prepare('SELECT s.name, c.name AS company FROM application a JOIN students s ON s.student_id=a.student_id JOIN drive d ON d.drive_id=a.drive_id LEFT JOIN company c ON c.company_id=d.company_id WHERE a.application_id=?'); $stmt->bind_param('i', $appId); $stmt->execute(); $application = $stmt->get_result()->fetch_assoc(); if (!$application) { header('Location: view_applicants.php'); exit(); }
admin_page_start('Update application', 'applicants'); ?>
<section class="page-heading"><h1>Update application status</h1><p><?= htmlspecialchars($application['name']) ?> · <?= htmlspecialchars($application['company'] ?? 'Company drive') ?></p></section><section class="card portal-card" style="max-width:520px"><form method="post"><div class="field"><label for="status">New status</label><select id="status" name="status"><?php foreach ($allowed as $status): ?><option><?= $status ?></option><?php endforeach; ?></select></div><?php if ($error): ?><p class="error"><?= htmlspecialchars($error) ?></p><?php endif; ?><div class="action-row"><button class="btn" type="submit">Save status</button><a class="btn" href="view_applicants.php">Cancel</a></div></form></section><?php admin_page_end(); ?>
